28	pub(crate) struct MigrationOptions {
29	    /// Migrate inspired rules from eslint and its plugins?
30	    pub(crate) include_inspired: bool,
31	    /// Migrate nursery rules from eslint and its plugins?
32	    pub(crate) include_nursery: bool,
33	}
