127	fn run_valid_tsconfig(input: &'static str, _: &str, _: &str, _: &str) {
128	    let input_file = Utf8Path::new(input);
129	    let file_name = input_file.file_name().unwrap();
130	    let input_code = read_to_string(input_file)
131	        .unwrap_or_else(|err| panic!("failed to read {input_file:?}: {err:?}"));
132	
133	    let mut project = NodeJsPackage::default();
134	    match input_file.extension().map(str::as_bytes) {
135	        Some(b"json") => {
136	            let parsed = parse_json(
137	                input_code.as_str(),
138	                JsonParserOptions::default().with_allow_comments(),
139	            );
140	            project.insert_serialized_tsconfig(&parsed.tree(), input_file);
141	        }
142	        _ => {
143	            panic!("Extension not supported");
144	        }
145	    };
146	
147	    let result = project.analyze();
148	
149	    assert!(
150	        !project.has_errors() && result.diagnostics.is_empty(),
151	        "The file {input} should not have diagnostics, but it has some./"
152	    );
153	
154	    let mut snapshot_result = String::new();
155	
156	    let strip_prefix = |path: &mut Utf8PathBuf| {
157	        if path.to_string().is_empty() {
158	            return;
159	        }
160	
161	        assert!(path.is_absolute());
162	        let mut stripped_path = Utf8PathBuf::from("<PREFIX>");
163	        let mut past_prefix = false;
164	        for component in path.components() {
165	            if past_prefix {
166	                stripped_path.push(component);
167	            } else if component == Utf8Component::Normal("tests") {
168	                past_prefix = true;
169	            }
170	        }
171	        *path = stripped_path;
172	    };
173	
174	    let mut tsconfig = project.tsconfig.unwrap();
175	    strip_prefix(&mut tsconfig.path);
176	    strip_prefix(&mut tsconfig.compiler_options.paths_base);
177	    tsconfig
178	        .compiler_options
179	        .base_url
180	        .as_mut()
181	        .map(strip_prefix);
182	
183	    snapshot_result.push_str("## Input\n\n");
184	    snapshot_result.push_str(&input_code);
185	    snapshot_result.push_str("\n\n");
186	    snapshot_result.push_str("## Data structure\n\n");
187	    snapshot_result.push_str(&format!("{tsconfig:#?}").replace("\\\\", "/"));
188	
189	    insta::with_settings!({
190	        prepend_module_to_snapshot => false,
191	        snapshot_path => input_file.parent().unwrap(),
192	    }, {
193	        insta::assert_snapshot!(file_name, snapshot_result, file_name);
194	    });
195	}
